def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return history[0][1]
    if n == 3:
        if history[1][1] == 'D' and history[2][1] == 'D':
            return 'D'
        return 'C'

    last = history[-1]
    opp_last = last[1]
    my_last = last[0]

    # Count recent outcomes
    recent = history[-8:]
    opp_c = sum(1 for _, o in recent if o == 'C')
    opp_d = len(recent) - opp_c
    my_c = sum(1 for m, _ in recent if m == 'C')

    # Detect likely always-D or mostly-D
    total_opp_d = sum(1 for _, o in history if o == 'D')
    total_opp_c = n - total_opp_d

    # If opponent is heavily defecting, switch to punishment/defect
    if total_opp_d > 0 and total_opp_c == 0:
        return 'D'

    # If opponent has defected a lot recently, defect back
    if opp_d >= 5:
        return 'D'

    # If opponent just defected after we cooperated, retaliate
    if opp_last == 'D' and my_last == 'C':
        # But if opponent pattern is alternating, maybe cooperate
        if n >= 4:
            if history[-2][1] == 'C' and history[-3][1] == 'D' and history[-4][1] == 'C':
                return 'D'
            if history[-2][1] == 'D' and history[-3][1] == 'C' and history[-4][1] == 'D':
                return 'C'
        return 'D'

    # If we defected and opponent cooperated, return to cooperation
    if my_last == 'D' and opp_last == 'C':
        return 'C'

    # If both cooperated, stay cooperative
    if my_last == 'C' and opp_last == 'C':
        # Occasionally test? No, keep cooperating in friendly matches
        # But if near end, exploit slightly
        remaining = 100 - n
        if remaining <= 2:
            return 'C'
        # Try to detect if opponent is naive cooperator
        if total_opp_d == 0:
            # They never defected; exploit at end
            if remaining <= 3:
                return 'D'
            return 'C'
        return 'C'

    # If both defected, try to break out
    if my_last == 'D' and opp_last == 'D':
        # Attempt reconciliation if opponent seems not purely defective
        if total_opp_c > 0 and recent.count(('D', 'C')) > 0:
            return 'C'
        # Otherwise defect
        return 'D'

    return 'C'

